import json,re
from docx import Document

with open('employee_data.json') as f:
    data=json.load(f)

relocation_yes = str(data.get('RELOCATION_PACKAGE','')).strip().lower()=='yes'

def replace_text(text):
    # handle conditional
    if '{{IF_RELOCATION}}' in text:
        if relocation_yes:
            text = text.replace('{{IF_RELOCATION}}','').replace('{{END_IF_RELOCATION}}','')
        else:
            text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}','',text)
    # replace placeholders
    for k,v in data.items():
        text = text.replace('{{'+k+'}}', str(v))
    return text


doc=Document('offer_letter_template.docx')

# process body paragraphs
for p in list(doc.paragraphs):
    if '{{' in p.text:
        new_text=replace_text(p.text)
        if new_text.strip()=='' :
            # remove paragraph
            p._element.getparent().remove(p._element)
        else:
            p.text=new_text

# process headers/footers
for section in doc.sections:
    for part in (section.header, section.footer):
        for p in part.paragraphs:
            if '{{' in p.text:
                p.text = replace_text(p.text)

# process tables too, if any
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                if '{{' in p.text:
                    p.text = replace_text(p.text)

out_path='/root/offer_letter_filled.docx'
doc.save(out_path)
print('saved',out_path)
